  function activityPage(){const events=eventsFiltered();return heading('Every event. The full story.','Who did what, when it happened, and which task and version it changed.',button(icon('download')+' Export activity','export-activity',''))+prototype()+`<div class="toolbar"><select class="filter" id="event-role" aria-label="Filter activity team">${options(['All teams',...E.roles],eventRole)}</select><select class="filter" id="event-date" aria-label="Filter activity date">${option('today',eventDate).replace('>today<','>Today · IST<')}${option('all',eventDate).replace('>all<','>All dates<')}</select><span class="filter-count">${events.length} events</span></div><section class="panel">${events.length?`<div class="table-wrap"><table class="activity-table"><thead><tr><th>Timestamp · IST</th><th>Person / team</th><th>Action</th><th>Task / version</th><th>Origin</th></tr></thead><tbody>${events.map(e=>`<tr ${e.taskId?`data-task="${e.taskId}" tabindex="0" role="button"`:''}><td class="mono">${date(e.at)}<br><strong>${time(e.at)}</strong></td><td><div class="row">${avatar(e.actor,'green')}<div>${esc(e.actor)}<br><span class="muted">${e.role}</span></div></div></td><td><div class="event-action">${esc(e.action)}</div><div class="event-detail">${esc(e.detail)}</div></td><td>${e.taskId||'Reference library'}${e.taskId?`<br><span class="muted">${typeof e.version==='number'?'Video v'+e.version:esc(e.version)}</span>`:''}</td><td><span class="demo-chip">${e.demo?'Seeded example':'Your test action'}</span></td></tr>`).join('')}</tbody></table></div>`:empty('No events for this filter','Try all teams or all dates.')}</section>`+footer();}
