  function renderMain(){if(role==='Admin'&&window.TrackerAdmin){window.TrackerAdmin.mount(document.querySelector('#main-content'),view);return;}const renderers={overview,tasks:()=>tasksPage(),archive:()=>tasksPage(true),approvals:approvalsPage,library:libraryPage,references:referencesPage,activity:activityPage,agent:agentPage,settings:settingsPage};document.querySelector('#main-content').innerHTML=(renderers[view]||overview)();}
