  function commentsBlock(t){const canComment=t.status!=='archived';return `<div class="detail-panel"><h3>${icon('comment')}Comments & feedback <span class="count">${t.comments.length}</span></h3>${t.comments.map(c=>`<div class="comment ${c.resolved?'resolved':''}"><div class="row">${avatar(c.by,'purple')}<strong>${esc(c.by)}</strong><time title="${fullTime(c.at)}">${time(c.at)}</time></div><p>${esc(c.text)}</p><div class="comment-tools"><span class="tag ${c.resolved?'green':c.blocking?'red':'gray'}">${c.resolved?'Resolved':c.blocking?'Blocking':'Comment'} · ${typeof c.version==='number'?'v'+c.version:esc(c.version)}</span>${!c.resolved&&c.role===role&&['Brand','Social'].includes(role)?`<button class="text-btn" data-act="resolve-comment" data-id="${c.id}">Resolve ${icon('check')}</button>`:!c.resolved&&!c.addressed&&['Video','Social'].includes(role)?`<button class="text-btn" data-act="address-comment" data-id="${c.id}">Mark addressed</button>`:c.addressed&&!c.resolved?'<span class="muted" style="font-size:8px">Awaiting reviewer confirmation</span>':''}</div></div>`).join('')||'<p class="muted" style="font-size:10px">No feedback yet.</p>'}${canComment?`<form id="comment-form" class="comment-compose"><textarea name="comment" class="comment-input" required placeholder="Leave clear, actionable feedback…" aria-label="Comment"></textarea><div class="row">${['Brand','Social'].includes(role)?'<label><input type="checkbox" name="blocking">Blocking feedback</label>':'<span>Comment as '+role+'</span>'}<button class="btn small" type="submit">Post ${icon('arrow')}</button></div></form>`:''}</div>`;}
  function assetView(t){const a=E.currentAsset(t);if(!a)return `<div class="detail-panel">${empty('Production starts with the approved script','No video version has been submitted yet.')}</div>`;if(a.kind==='local'&&a.url)return `<video class="video-box" controls src="${esc(a.url)}"></video><p class="card-note">Local video preview · available in this session only.</p>`;if(a.kind==='local')return `<div class="file-unavailable">${icon('video')} ${esc(a.name)}<br>This local preview was not uploaded to a server. Submit the file again to preview it after a reload.</div>`;if(a.kind==='link')return `<div class="detail-panel"><h3>${icon('link')}Video v${a.version}</h3><p class="muted" style="font-size:11px;margin-bottom:15px">${esc(a.name)}</p><a class="btn" href="${url(a.url)}" target="_blank" rel="noopener noreferrer">Open video link ${icon('arrow')}</a></div>`;return cover(t)+`<p class="card-note">Demo storyboard. Upload a local video or attach a link to preview real media.</p>`;}
  function metadataBlock(t){return `<div class="detail-panel"><h3>Task details</h3><dl class="metadata"><dt>Task ID</dt><dd>${t.id}</dd><dt>Product</dt><dd>${esc(t.product)}</dd><dt>Category</dt><dd>${esc(t.category)}</dd><dt>Format</dt><dd>${esc(t.type)}</dd><dt>Destination</dt><dd>${esc(t.destination)}</dd><dt>Social owner</dt><dd>${esc(t.socialOwner)}</dd><dt>Video editor</dt><dd>${['Admin','Brand'].includes(role)?`<select id="task-owner" aria-label="Video editor">${options(editors,t.videoOwner)}</select>`:esc(t.videoOwner)}</dd><dt>Priority</dt><dd>${['Admin','Brand','Social'].includes(role)?`<select id="task-priority" aria-label="Task priority">${options(['P0','P1','P2'],t.priority)}</select>`:priority(t)}</dd><dt>Due · IST</dt><dd>${fullTime(t.due)}</dd><dt>Last activity</dt><dd>${fullTime(t.updatedAt)}</dd><dt>Reference</dt><dd>${t.reference?`<a href="${url(t.reference)}" target="_blank" rel="noopener noreferrer" class="text-btn">Open reference ${icon('arrow')}</a>`:'No reference attached'}</dd></dl></div>`;}
